104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
107	        HttpHeaders headers = new HttpHeaders();
108	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
109	        if (this.clinicService.isRegistrationDateInFuture(owner.getRegistrationDate())) {
110	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
111	        }
112	        owner.setRegistrationDate(this.clinicService.resolveRegistrationDate(owner.getRegistrationDate()));
113	        if (this.clinicService.isDailyOwnerLimitReached(owner.getRegistrationDate())) {
114	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
115	        }
116	        if (this.clinicService.isCityAtCapacity(owner.getCity())) {
117	            return new ResponseEntity<>(HttpStatus.CONFLICT);
118	        }
119	        // Assign the deterministic householdId (derived from last name and postcode) so owners in
120	        // the same household share it automatically and it forms part of the identity key.
121	        this.clinicService.assignHousehold(owner);
122	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
123	        // A second owner in an existing household (same last name and postcode) is a household
124	        // duplicate; reject it unless the client declares the shared household, in which case it is
125	        // created as a declared member.
126	        if (this.clinicService.existsOwnerInHousehold(owner) && !declaredHouseholdMember) {
127	            return new ResponseEntity<>(HttpStatus.CONFLICT);
128	        }
129	        // Reject an exact duplicate: an owner whose whole identity key (normalized telephone,
130	        // email and householdId) already exists.
131	        if (this.clinicService.existsOwnerWithIdentityKey(owner)) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        owner.setNamesakeCount((int) this.clinicService.countNamesakes(owner.getFirstName(), owner.getLastName()));
135	        owner.setHouseholdSize((int) this.clinicService.countHouseholdMembers(owner));
136	        owner.setBulkSignupWarning(this.clinicService.isBulkSignupWarranted(owner.getRegistrationDate()));
137	        // Flag a soft match unless this is a declared household member (a declared member is not a
138	        // suspected duplicate): an existing owner sharing this owner's last name and postcode with a
139	        // different telephone.
140	        if (!declaredHouseholdMember) {
141	            Integer possibleDuplicateOf = this.clinicService.findPossibleDuplicateOwnerId(owner);
142	            owner.setPossibleDuplicate(possibleDuplicateOf != null);
143	            owner.setPossibleDuplicateOf(possibleDuplicateOf);
144	        }
145	        this.clinicService.saveOwner(owner);
146	        this.ownerAuditor.auditCreated(owner);
147	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
148	        headers.setLocation(UriComponentsBuilder.newInstance()
149	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
150	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
151	    }
